def merge(*dicts, **kwargs):
    """ Merge a collection of dictionaries

    >>> merge({1: 'one'}, {2: 'two'})
    {1: 'one', 2: 'two'}

    Later dictionaries have precedence

    >>> merge({1: 2, 3: 4}, {3: 3, 4: 4})
    {1: 2, 3: 3, 4: 4}

    See Also:
        merge_with
    """
    if len(dicts) == 1 and not isinstance(dicts[0], (dict, Mapping)):
        dicts = dicts[0]
    factory = _get_factory(merge, kwargs)
    if factory is None:
        # Determine factory from first dict if possible
        if isinstance(dicts, (tuple, list)) and dicts:
            factory = type(dicts[0])
        else:
            factory = dict

    rv = factory()
    for d in dicts:
        rv.update(d)
    return rv

