def merge(*dicts, **kwargs):
    """ Merge a collection of dictionaries

    >>> merge({1: 'one'}, {2: 'two'})
    {1: 'one', 2: 'two'}

    Later dictionaries have precedence

    >>> merge({1: 2, 3: 4}, {3: 3, 4: 4})
    {1: 2, 3: 3, 4: 4}

    See Also:
        merge_with
    """
    if len(dicts) == 1 and not isinstance(dicts[0], (dict, Mapping)):
        dicts = dicts[0]
    factory = kwargs.pop('factory', None)
    if kwargs:
        raise TypeError("{}() got an unexpected keyword argument "
                        "'{}'".format(merge.__name__, kwargs.popitem()[0]))
    if factory is None:
        if dicts:
            if isinstance(dicts, (dict, Mapping)):
                factory = type(dicts)
            elif isinstance(dicts, list) or isinstance(dicts, tuple):
                factory = type(dicts[0]) if dicts else dict
            else:
                # iterable, peek at first element
                try:
                    first = next(iter(dicts))
                    factory = type(first)
                except (StopIteration, TypeError):
                    factory = dict
        else:
            factory = dict

    rv = factory()
    for d in dicts:
        rv.update(d)
    return rv
